// === ESTRUCTURA DEL PATRÓN TEMPLATE METHOD ===

// 1. Clase Abstracta con Template Method
abstract class DataExporter {
  // Template Method: define el esqueleto del algoritmo
  export(filePath: string) {
    const data = this.extractData(filePath);
    const formatted = this.formatData(data);
    const output = this.generateOutput(formatted);
    this.send(output);
  }

  // Métodos abstractos: las subclases DEBEN implementarlos
  protected abstract extractData(path: string): RawData[];
  protected abstract formatData(data: RawData[]): FormattedData;
  protected abstract generateOutput(data: FormattedData): string;

  // Método con implementación por defecto (opcional override)
  protected send(output: string) {
    console.log(`Enviando: ${output.substring(0, 50)}...`);
  }
}

// 2. Subclases Concretas
class CSVExporter extends DataExporter {
  protected extractData(path: string): RawData[] {
    return readCSV(path);
  }

  protected formatData(data: RawData[]): FormattedData {
    return data.map(row => row.join(','));
  }

  protected generateOutput(data: FormattedData): string {
    return data.join('\n');
  }
}

class JSONExporter extends DataExporter {
  protected extractData(path: string): RawData[] {
    return readJSON(path);
  }

  protected formatData(data: RawData[]): FormattedData {
    return JSON.stringify(data);
  }

  protected generateOutput(data: FormattedData): string {
    return data;
  }
}

// Uso:
const csvExporter = new CSVExporter();
csvExporter.export('data.json'); // Ejecuta: extract → format → generate → send

const jsonExporter = new JSONExporter();
jsonExporter.export('data.csv'); // Misma secuencia, diferente implementación

