class CSVReportGenerator {
  generateReport(data: Data[]) {
    const header = 'name,value';
    const rows = data.map(d => `${d.name},${d.value}`);
    const csv = [header, ...rows].join('\n');
    fs.writeFileSync('report.csv', csv);
  }
}

