// 1. Clase base con template method
abstract class ReportGenerator {
  generateReport(data: Data[]) {
    const formatted = this.formatData(data);
    const output = this.generateOutput(formatted);
    this.save(output);
  }

  protected abstract formatData(data: Data[]): string[];
  protected abstract generateOutput(lines: string[]): string;

  protected save(output: string) {
    fs.writeFileSync(`report.${this.getExtension()}`, output);
  }

  protected abstract getExtension(): string;
}

// 2. Subclases con implementación específica
class PDFReportGenerator extends ReportGenerator {
  protected formatData(data: Data[]) {
    return data.map(d => `${d.name}: ${d.value}`);
  }
  protected generateOutput(lines: string[]) {
    return htmlToPDF(`<html><body>${lines.join('<br>')}</body></html>`);
  }
  protected getExtension() { return 'pdf'; }
}

class CSVReportGenerator extends ReportGenerator {
  protected formatData(data: Data[]) {
    return data.map(d => `${d.name},${d.value}`);
  }
  protected generateOutput(lines: string[]) {
    return ['name,value', ...lines].join('\n');
  }
  protected getExtension() { return 'csv'; }
}

